def install(apps, schema_editor):
    """Use the four designed banners (desktop + mobile) as the homepage hero slides."""
    HomeSection = apps.get_model('shop', 'HomeSection')
    HomeCard = apps.get_model('shop', 'HomeCard')
    hero = HomeSection.objects.filter(kind='hero', active=True).order_by('sort_order', 'id').first()
    if not hero:
        return
    alt, title, link = BANNERS[0]
    hero.image = ''; hero.image_path = B.format(1, 'desktop')
    hero.mobile_image = ''; hero.mobile_image_path = B.format(1, 'mobile')
    hero.alt_text, hero.image_title = alt, title
    hero.eyebrow = hero.title = hero.subtitle = hero.text = ''
    hero.button_url = hero.button_url or link
    hero.save()
    cards = list(HomeCard.objects.filter(section=hero).order_by('sort_order', 'id'))
    for n, (alt, title, link) in enumerate(BANNERS[1:], start=2):
        c = cards[n - 2] if len(cards) >= n - 1 else HomeCard(section=hero, sort_order=n)
        c.image = ''; c.image_path = B.format(n, 'desktop')
        c.mobile_image = ''; c.mobile_image_path = B.format(n, 'mobile')
        c.alt_text, c.image_title = alt, title
        c.title = c.label = c.caption = c.text = c.bullets = ''
        c.button_label = ''
        c.url = c.url or link
        c.active = True
        c.save()
    for c in cards[3:]:  # any older extra slides are switched off (not deleted)
        c.active = False
        c.save(update_fields=['active'])


